# AI-written helper (not from the book): which cell holds filter k?
def cell_of(k, n=8, box=150, margin=5):
    i, j = divmod(k, n)
    top, left = (box + margin) * i, (box + margin) * j
    return (top, top + box), (left, left + box)

print(cell_of(27))  # ((465, 615), (465, 615))
